const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'Fermer le menu':'Ouvrir le menu');nav.classList.toggle('open',open)});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false')}));
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',b===button)});document.querySelectorAll('.project').forEach(p=>p.hidden=button.dataset.filter!=='all'&&p.dataset.category!==button.dataset.filter)}));
const modal=document.querySelector('#modal'),content=document.querySelector('#modal-content');const projects=[['Sola — Le soleil en bouteille','Exploration fictive · Stratégie / Identité / Packaging','Le défi : donner à une huile d’olive de Provence un territoire de marque lumineux, simple et reconnaissable.','La direction : une typographie expressive, une palette végétale et un packaging qui met le produit au premier plan. Un système conçu pour vivre aussi bien en rayon que sur les réseaux sociaux.'],['Horizon — L’appel du dehors','Exploration fictive · Direction artistique / UX / Web','Le défi : imaginer une expérience digitale pour un collectif outdoor qui invite à quitter son écran.','La direction : de grands paysages graphiques, un ton direct et un parcours centré sur la découverte des sorties. La création relie l’envie d’explorer à une prochaine action claire.'],['Nuit Libre — Faire vibrer la ville','Exploration fictive · Campagne / Social / Contenu','Le défi : créer une campagne culturelle qui transforme la curiosité en envie de participer.','La direction : un contraste violet et citron, des compositions typographiques libres et des messages courts. Une identité déclinable en affiches, stories et publications.']];function show(title,paras){content.replaceChildren();const h=document.createElement('h2');h.textContent=title;content.append(h);paras.forEach(t=>{const p=document.createElement('p');p.textContent=t;content.append(p)});modal.showModal()}document.querySelectorAll('[data-project]').forEach(b=>b.addEventListener('click',()=>{const [title,...paras]=projects[Number(b.dataset.project)];show(title,paras)}));document.querySelector('.close').addEventListener('click',()=>modal.close());modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)modal.close()}});document.querySelectorAll('[data-info]').forEach(b=>b.addEventListener('click',()=>b.dataset.info==='legal'?show('Informations légales',['Élan est une marque de démonstration. Les projets Sola, Horizon et Nuit Libre sont des concepts fictifs et ne constituent pas des références clients.','Avant une exploitation commerciale, les informations de l’entreprise éditrice, ses coordonnées et les mentions applicables doivent être renseignées.']):show('Confidentialité',['Ce site ne contient aucun outil de mesure d’audience et ne dépose aucun cookie de suivi.','Le formulaire génère un fichier texte localement sur votre appareil. Les données saisies ne sont transmises à aucun serveur et ne sont pas conservées par le site.','Les polices sont chargées depuis Google Fonts, ce qui implique une connexion à ce service.'])));document.querySelector('#brief').addEventListener('submit',e=>{e.preventDefault();const d=new FormData(e.target);const text=`BRIEF PROJET — ÉLAN\n\nNom : ${d.get('name')}\nE-mail : ${d.get('email')}\nEntreprise : ${d.get('company')}\nExpertise : ${d.get('service')}\n\nProjet :\n${d.get('message')}\n\nDocument préparatoire — aucun envoi effectué.`;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='mon-brief-elan.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.querySelector('#form-status').textContent='Votre brief a été téléchargé. Aucun envoi n’a été effectué.'});
